#!/usr/bin/env node
/**
 * sync-wiki-to-brain.mjs — publish compiled wiki pages into Open Brain.
 *
 * Reads compiled-wiki/{entities,topics}/*.md (already generated by
 * wiki-compiler) and upserts each page into public.thoughts as a
 * wiki_entity / wiki_topic thought so the dashboard /wiki route renders
 * them live via the REST gateway. Idempotent: re-runs update in place.
 *
 * Env (./.env.local at cwd, then process.env):
 *   OPEN_BRAIN_URL           https://<ref>.supabase.co
 *   OPEN_BRAIN_SERVICE_KEY   service role key (local/server only — never commit)
 *
 * Usage:
 *   node recipes/wiki-compiler/sync-wiki-to-brain.mjs \
 *     [--in-dir ./compiled-wiki] [--only entities|topics] [--dry-run]
 */
import { readFileSync, existsSync, readdirSync } from "node:fs";
import { resolve, join } from "node:path";
import { fileURLToPath } from "node:url";

const CWD = process.cwd();

// ── Pure helpers (unit-tested) ───────────────────────────────────────────

export function splitFrontmatter(raw) {
  const m = raw.match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/);
  if (!m) return { meta: {}, body: raw };
  const meta = {};
  for (const line of m[1].split("\n")) {
    const p = line.match(/^([a-zA-Z_][a-zA-Z0-9_]*):\s*(.*?)\s*$/);
    if (p) meta[p[1]] = p[2].replace(/^["']|["']$/g, "");
  }
  return { meta, body: m[2] };
}

export function sourceTypeForDir(dir) {
  if (dir === "entities") return "wiki_entity";
  if (dir === "topics") return "wiki_topic";
  throw new Error(`unknown wiki dir: ${dir}`);
}

export function buildWikiThought(dir, filename, raw) {
  const slug = filename.replace(/\.md$/, "");
  const { meta, body } = splitFrontmatter(raw);
  const title = meta.title || slug.replace(/-/g, " ");
  return {
    content: body.trim(),
    type: "reference",
    source_type: sourceTypeForDir(dir),
    metadata: {
      wiki_slug: slug,
      wiki_title: title,
      wiki_type: meta.type || { entities: "entity", topics: "topic" }[dir],
      generated_at: meta.generated_at || null,
      compiled_by: "wiki-compiler",
    },
  };
}

// ── env ──────────────────────────────────────────────────────────────────

function readEnvLocal() {
  const path = resolve(CWD, ".env.local");
  if (!existsSync(path)) return {};
  const out = {};
  for (const line of readFileSync(path, "utf8").split(/\r?\n/)) {
    const m = line.match(/^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*?)\s*$/);
    if (m) out[m[1]] = m[2].replace(/^["']|["']$/g, "");
  }
  return out;
}

// ── PostgREST client (service role — local only) ─────────────────────────

class BrainApi {
  constructor(projectUrl, serviceKey) {
    this.base = `${projectUrl.replace(/\/+$/, "")}/rest/v1`;
    this.headers = {
      apikey: serviceKey,
      Authorization: `Bearer ${serviceKey}`,
      "Content-Type": "application/json",
    };
  }

  async findBySlug(sourceType, slug) {
    const qs =
      `thoughts?select=id&source_type=eq.${encodeURIComponent(sourceType)}` +
      `&metadata->>wiki_slug=eq.${encodeURIComponent(slug)}&limit=1`;
    const res = await fetch(`${this.base}/${qs}`, { headers: this.headers });
    if (!res.ok)
      throw new Error(`GET ${res.status}: ${(await res.text()).slice(0, 300)}`);
    const rows = await res.json();
    return rows[0]?.id ?? null;
  }

  async insert(thought) {
    const res = await fetch(`${this.base}/thoughts`, {
      method: "POST",
      headers: { ...this.headers, Prefer: "return=representation" },
      body: JSON.stringify(thought),
    });
    if (!res.ok)
      throw new Error(`POST ${res.status}: ${(await res.text()).slice(0, 300)}`);
    return (await res.json())[0]?.id;
  }

  async update(id, thought) {
    const res = await fetch(`${this.base}/thoughts?id=eq.${id}`, {
      method: "PATCH",
      headers: this.headers,
      body: JSON.stringify({
        content: thought.content,
        type: thought.type,
        source_type: thought.source_type,
        metadata: thought.metadata,
      }),
    });
    if (!res.ok)
      throw new Error(`PATCH ${res.status}: ${(await res.text()).slice(0, 300)}`);
  }
}

// ── main ───────────────────────────────────────────────────────────────────

function parseArgs(argv) {
  const args = { inDir: "./compiled-wiki", only: null, dryRun: false, help: false };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--in-dir") args.inDir = argv[++i];
    else if (a === "--only") args.only = argv[++i];
    else if (a === "--dry-run") args.dryRun = true;
    else if (a === "--help" || a === "-h") args.help = true;
  }
  return args;
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (args.help) {
    console.log(
      "Usage: node sync-wiki-to-brain.mjs [--in-dir ./compiled-wiki] [--only entities|topics] [--dry-run]",
    );
    process.exit(0);
  }

  const fileEnv = readEnvLocal();
  const url = fileEnv.OPEN_BRAIN_URL || process.env.OPEN_BRAIN_URL;
  const key = fileEnv.OPEN_BRAIN_SERVICE_KEY || process.env.OPEN_BRAIN_SERVICE_KEY;
  if (!url) {
    console.error("ERROR: OPEN_BRAIN_URL missing (set in .env.local).");
    process.exit(2);
  }
  if (!key) {
    console.error("ERROR: OPEN_BRAIN_SERVICE_KEY missing (set in .env.local).");
    process.exit(2);
  }

  const inDir = resolve(CWD, args.inDir);
  const dirs = (args.only ? [args.only] : ["topics", "entities"]).filter((d) =>
    existsSync(join(inDir, d)),
  );
  if (dirs.length === 0) {
    console.error(`ERROR: no entities/ or topics/ under ${inDir}. Run wiki-compiler first.`);
    process.exit(2);
  }

  const api = new BrainApi(url, key);
  let inserted = 0,
    updated = 0,
    failed = 0;

  for (const dir of dirs) {
    const files = readdirSync(join(inDir, dir)).filter(
      (f) => f.endsWith(".md") && f !== "INDEX.md",
    );
    for (const f of files) {
      const raw = readFileSync(join(inDir, dir, f), "utf8");
      const thought = buildWikiThought(dir, f, raw);
      if (args.dryRun) {
        console.log(
          `  [dry] ${thought.source_type}  ${thought.metadata.wiki_slug}  (${thought.content.length} chars)`,
        );
        continue;
      }
      try {
        const existing = await api.findBySlug(
          thought.source_type,
          thought.metadata.wiki_slug,
        );
        if (existing) {
          await api.update(existing, thought);
          updated++;
        } else {
          await api.insert(thought);
          inserted++;
        }
      } catch (err) {
        failed++;
        console.error(`  [fail] ${thought.metadata.wiki_slug}: ${err.message}`);
      }
    }
  }

  console.log(`Done. inserted=${inserted} updated=${updated} failed=${failed}`);
  if (failed > 0) process.exit(1);
}

// Run main only when executed directly (not when imported by tests).
// Robust entry check (matches compile-wiki.mjs): compare resolved paths, not
// a hand-built file:// URL (encoding/path differences make the latter brittle).
if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main().catch((err) => {
    console.error(err);
    process.exit(1);
  });
}
